SELECT category, SUM(rating * weight) / SUM(weight) AS avg_rating
FROM (
    SELECT category, rating, exp((emb <#> $1) / 0.001) AS weight
    FROM reviews
) AS weights
GROUP BY category;

SELECT category, SUM(rating * weight) / SUM(weight) AS weighted_avg_rating
FROM (
    SELECT category, rating, EXP(cosine_similarity(emb, $1) / 0.001) AS weight
    FROM reviews
) sub
GROUP BY category;

SELECT category, SUM(rating * weight) / SUM(weight) AS weighted_avg_rating
FROM (
    SELECT category, rating, EXP(dot_product(emb, $1) / 0.001) AS weight
    FROM reviews
) AS subquery
GROUP BY category;

SELECT category, SUM(rating * exp_sim) / SUM(exp_sim) AS weighted_avg_rating
FROM (
    SELECT category, rating, EXP((emb #> $1) / 0.1) AS exp_sim
    FROM reviews
) sub
GROUP BY category;
